'use strict';
const path=require('node:path'),crypto=require('node:crypto'),assert=require('node:assert/strict'),{test}=require('node:test');
const {fixture,settle,wait,read,input}=require('./fixture.cjs');
const D=__dirname;
const invariant=d=>({native:[...d.querySelectorAll('li.example-card')].map(n=>{const c=n.cloneNode(true);c.querySelectorAll('.sf-native-ownership-history').forEach(x=>x.replaceChildren());return crypto.createHash('sha256').update(c.innerHTML).digest('hex')}),frequency:[...d.querySelectorAll('.frequency-count,.sf-count')].map(n=>n.textContent),groupTargets:[...d.querySelectorAll('.sf-group-member-evidence')].map(n=>n.innerHTML)});
test('real original one/request inserts both authenticated history parts without replacing source rows',async()=>{
 const f=await fixture();try{assert.equal(f.d.querySelector('script.anki-final-reviewed-data').dataset.nativeState,'ready',f.d.querySelector('.anki-final-status')?.textContent);const before=invariant(f.d),rows=[...f.d.querySelectorAll('li.example-card')];for(const detail of f.owners)await f.open(detail);assert.equal(f.handle.stats().invalid,null);assert.equal(f.handle.refresh(),true);assert.deepEqual(invariant(f.d),before);assert.ok(rows.every(n=>n.isConnected));for(const detail of f.owners){assert.equal(detail.querySelectorAll('script.as-manifest').length,1);assert.equal(detail.querySelector('script.as-manifest').dataset.asLoadedParts,'1');assert.equal(detail.querySelectorAll('.card-chunk').length>0,true);const pre=detail.querySelector('pre[data-native-history-media]');await f.open(pre.parentElement);assert.equal(pre.textContent,input.media[pre.dataset.nativeHistoryMedia].text);assert.equal(pre.dataset.nativeHistoryReady,'true');}assert.equal(f.handle.stats().invalid,null);assert.equal(f.handle.refresh(),true);}finally{f.close()}
});
if(!process.env.BASELINE){
 test('original AF hash failure text remains retryable and later authentic success is accepted',async()=>{const f=await fixture({badAF:true});try{await f.open(f.owners[0]);const pre=f.owners[0].querySelector('pre[data-native-history-media]');await f.open(pre.parentElement);assert.equal(pre.textContent,'证据载入失败：完整证据校验失败');assert.notEqual(pre.dataset.nativeHistoryReady,'true');assert.equal(f.handle.stats().invalid,null);f.w.AnkiFinalHistoryEvidence[pre.dataset.nativeHistorySha]=input.media[pre.dataset.nativeHistoryMedia].text;await f.open(pre.parentElement);assert.equal(pre.dataset.nativeHistoryReady,'true');assert.equal(pre.textContent,input.media[pre.dataset.nativeHistoryMedia].text);assert.equal(f.handle.stats().invalid,null);}finally{f.close()}});
 test('original part SHA failure preserves closed source and original failure state',async()=>{const f=await fixture({badPart:true});try{const before=invariant(f.d);await f.open(f.owners[0]);assert.equal(f.owners[0].querySelector('.sf-sentence-pair'),null);assert.equal(f.owners[0].querySelector('script.as-manifest').dataset.asState,'failed');assert.match(f.d.querySelector('.anki-final-status').textContent,/本地片段校验失败/);assert.deepEqual(invariant(f.d),before);assert.equal(f.handle.stats().invalid,null);}finally{f.close()}});
 test('outer owner cancellation after original part and AF digest awaits writes nothing further',async()=>{let resume,waiting;const barrier=()=>new Promise(r=>{resume=r;waiting=true});const f=await fixture({digestBarrier:barrier});try{const detail=f.owners[0];detail.open=true;detail.dispatchEvent(new f.w.Event('toggle'));await wait(()=>waiting);const before=detail.innerHTML;f.cancel();resume();await settle();await settle();assert.equal(detail.innerHTML,before);assert.notEqual(detail.querySelector('script.as-manifest').dataset.asState,'ready');assert.equal(f.d.querySelector('.anki-final-status'),null);}finally{f.close()}});
 test('unknown owner, changed source pin, manifest and unpinned native/reader nodes are rejected before insert',async()=>{
  for(const change of [p=>p.historySlots[0].sourceArtifactSha256='0'.repeat(64),p=>p.historySlots[0].region.ownerPath[0]++,p=>p.historySlots[0].manifestText+=' ']){const f=await fixture({changeProfile:change});try{assert.equal(f.d.querySelector('script.anki-final-reviewed-data').dataset.nativeState,'failed');assert.equal(f.handle,undefined);}finally{f.close()}}
  for(const tag of ['li','a']){const f=await fixture();try{const spec=f.profile.historySlots[0],manifest=f.owners[0].querySelector('script.as-manifest'),anchor=manifest.parentElement,slot={manifest,anchor,holder:f.owners[0],detail:f.owners[0],kind:'disclosure',panel:null,value:JSON.parse(spec.manifestText),at:0},t=f.d.createElement('template');t.innerHTML=input.parts[spec.parts[0].sha256];f.w.AnkiSlimDecode(t.content);const extra=f.d.createElement(tag);extra.className=tag==='li'?'example-card':'sentence-jump';t.content.append(extra);const before=f.owners[0].innerHTML;assert.throws(()=>f.handle.authorizeHistoryPart(slot,spec.parts[0],t.content),/history part scope/);assert.equal(f.owners[0].innerHTML,before);assert.match(f.handle.stats().invalid,/history part scope/);}finally{f.close()}}
 });
 test('original chunks delegate remains active for all inserted history spans and audit/summary mutations still invalidate',async()=>{const f=await fixture();try{for(const detail of f.owners)await f.open(detail);const chunk=f.owners[0].querySelector('.card-chunk'),before=chunk.textContent;chunk.dispatchEvent(new f.w.MouseEvent('click',{bubbles:true,cancelable:true}));await settle();assert.ok(f.d.querySelector('.card-chunk-active'));assert.equal(chunk.textContent,before);assert.equal(f.handle.stats().invalid,null);chunk.dispatchEvent(new f.w.MouseEvent('click',{bubbles:true,cancelable:true}));f.d.dispatchEvent(new f.w.KeyboardEvent('keydown',{key:'Escape',bubbles:true}));await settle();assert.equal(f.handle.stats().invalid,null);f.owners[0].querySelector('summary').append('tamper');await settle();assert.match(f.handle.stats().invalid,/history child graph changed|history text changed/);}finally{f.close()}});
 test('AF await cancellation cannot write evidence or turn stale owner into a current media failure',async()=>{const f=await fixture();try{await f.open(f.owners[0]);const pre=f.owners[0].querySelector('pre[data-native-history-media]'),before=pre.outerHTML;let resume,waiting=false;f.setDigestBarrier(()=>new Promise(r=>{resume=r;waiting=true}));pre.parentElement.open=true;pre.parentElement.dispatchEvent(new f.w.Event('toggle'));await wait(()=>waiting);f.cancel();resume();await settle();await settle();assert.equal(pre.outerHTML,before);assert.equal(f.d.querySelector('.anki-final-status'),null);}finally{f.close()}});
 test('AF successful hash followed by damaged owner is terminal invalidation, never re-authorized as ordinary media failure',async()=>{const f=await fixture();try{await f.open(f.owners[0]);const pre=f.owners[0].querySelector('pre[data-native-history-media]'),before=pre.outerHTML;let resume,waiting=false;f.setDigestBarrier(()=>new Promise(r=>{resume=r;waiting=true}));pre.parentElement.open=true;pre.parentElement.dispatchEvent(new f.w.Event('toggle'));await wait(()=>waiting);f.owners[0].querySelector('summary').append('external');await settle();assert.ok(f.handle.stats().invalid);resume();await settle();await settle();assert.equal(pre.outerHTML,before);assert.equal(pre.textContent.startsWith('证据载入失败：'),false);assert.match(f.d.querySelector('.anki-final-status').textContent,/Compiled card invalid/);}finally{f.close()}});
 test('all 70 real history chunks retain original hover/tap/re-tap/Escape results versus original loader',async()=>{
  const old=await fixture({legacyLoader:true}),next=await fixture();try{for(const f of [old,next])for(const detail of f.owners)await f.open(detail);const chunks=f=>f.owners.flatMap(detail=>[...detail.querySelectorAll('.card-chunk')]);const a=chunks(old),b=chunks(next);assert.equal(a.length,70);assert.equal(b.length,70);assert.deepEqual(old.owners.map(n=>n.innerHTML),next.owners.map(n=>n.innerHTML));const snapshot=f=>[...f.d.querySelectorAll('.card-chunk-active')].map(n=>[n.textContent,n.dataset.chunkIds,n.dataset.chunkSide]);for(let i=0;i<a.length;i++)for(const type of ['pointerover','click','click','keydown']){for(const [f,node]of [[old,a[i]],[next,b[i]]]){if(type==='keydown')f.d.dispatchEvent(new f.w.KeyboardEvent('keydown',{key:'Escape',bubbles:true}));else node.dispatchEvent(new f.w.MouseEvent(type,{bubbles:true,cancelable:true}));}await settle();assert.deepEqual(snapshot(old),snapshot(next),'history chunk '+i+' '+type);assert.equal(next.handle.stats().invalid,null);}assert.equal(next.handle.refresh(),true);}finally{old.close();next.close()}
 });
 test('adapter uses exact audited boundaries, leaves unknown pins byte-identical and rejects known drift',()=>{const adapt=new Function(read('adapter.js')+';return adaptCompiledHistorySlots;')();assert.equal(adapt(read('original-slim.js'),input.modulePin),read('prior-compiled-slim.js'));assert.equal(adapt('unknown bytes','0'.repeat(64)),'unknown bytes');assert.throws(()=>adapt(read('original-slim.js').replace('slot.holder.insertBefore(template.content, slot.anchor);','slot.holder.append(template.content);'),input.modulePin),/boundary differs/);});
 test('omitted/empty history capability preserves ordinary slotless compiled behavior',async()=>{const oldEnv=process.env.RUNTIME_SOURCE;process.env.RUNTIME_SOURCE=path.join(D,'runtime.js');const {fixture:ordinary}=require('../boundary-v2c/fixture.cjs');try{for(const explicit of [false,true]){const f=ordinary('abolish',(_d,p)=>{if(explicit)p.historySlots=[]});try{assert.equal(f.runtime.refresh(),true);const year=f.d||f.doc;const control=year.querySelector('[data-sf-filter]:not([data-sf-filter="all"])');control.click();await settle();assert.equal(f.runtime.stats().invalid,null);assert.equal(f.runtime.refresh(),true);}finally{f.close()}}}finally{if(oldEnv===undefined)delete process.env.RUNTIME_SOURCE;else process.env.RUNTIME_SOURCE=oldEnv}});
 test('augmented metadata and unchanged final HTML remain externally SHA-authenticated',()=>{const {verifyProfile}=require('../verify.cjs'),anchors=JSON.parse(read('anchors.json')),p=verifyProfile(read('profile.json'),read('final.html'),anchors);assert.equal(p.historySlots.length,2);assert.equal(p.bindings.historyScopeEvidenceSha256,crypto.createHash('sha256').update(read('scope-evidence.json')).digest('hex'));assert.throws(()=>verifyProfile(read('profile.json')+' ',read('final.html'),anchors),/external SHA/);});
}
